    if (kind === 'soft') return d[0];
    if (kind === 'hard') return d[1];
    return RISKY.has(a) || RISKY.has(b) ? `${d[0]} Обратная сторона соединения: ${d[1][0].toLowerCase()}${d[1].slice(1)}` : d[0];
