      const h = root.NATAL.houseOf(p.lon, toChart.cusps), id = base(p), sp = OVERLAY_SPECIAL[`${id}|${h}`];
      const slow = SLOW3.has(id) ? ' Медленная планета: её влияние фоновое, как у поколения.' : '';
      return who === 'partner'
